// keys: "21" ENTER
// expect: exit 42
// screen: 0 Number? 21
// screen: 1 Double is 42
char buf[8];
int main(void)
{
    int n;
    cls();
    print("Number? ");
    gets(buf, sizeof buf);
    n = atoi(buf) * 2;
    printf("Double is %d\n", n);
    return n;
}
